   287  void Leader::HandleCommissioningGet(Coap::Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
   288  {
   289      MeshCoP::Tlv tlv;
   290      uint16_t     offset = aMessage.GetOffset();
   291      uint8_t      tlvs[NetworkData::kMaxSize];
   292      uint8_t      length = 0;
   293
   294      while (offset < aMessage.GetLength())
   295      {
   296          aMessage.Read(offset, sizeof(tlv), &tlv);
   297
   298          if (tlv.GetType() == MeshCoP::Tlv::kGet)
   299          {
   300              length = tlv.GetLength();
   301              aMessage.Read(offset + sizeof(MeshCoP::Tlv), length, tlvs);
   302              break;
   303          }
   304
   305          offset += sizeof(tlv) + tlv.GetLength();
   306      }
   307
   308      SendCommissioningGetResponse(aMessage, aMessageInfo, tlvs, length);
   309  }
