   311  void Leader::SendCommissioningGetResponse(const Coap::Message &   aRequest,
   312                                            const Ip6::MessageInfo &aMessageInfo,
   313                                            const uint8_t *         aTlvs,
   314                                            uint8_t                 aLength)
   315  {
   316      otError        error = OT_ERROR_NONE;
   317      Coap::Message *message;
   318      uint8_t        index;
   319      uint8_t *      data   = NULL;
   320      uint8_t        length = 0;
   321
   322      VerifyOrExit((message = MeshCoP::NewMeshCoPMessage(Get<Coap::Coap>())) != NULL, error = OT_ERROR_NO_BUFS);
   323
   324      SuccessOrExit(error = message->SetDefaultResponseHeader(aRequest));
   325      SuccessOrExit(error = message->SetPayloadMarker());
   326
   327      for (NetworkDataTlv *cur                                            = reinterpret_cast<NetworkDataTlv *>(mTlvs);
   328           cur < reinterpret_cast<NetworkDataTlv *>(mTlvs + mLength); cur = cur->GetNext())
   329      {
   330          if (cur->GetType() == NetworkDataTlv::kTypeCommissioningData)
   331          {
   332              data   = cur->GetValue();
   333              length = cur->GetLength();
   334              break;
   335          }
   336      }
   337
   338      VerifyOrExit(data && length, error = OT_ERROR_DROP);
   339
   340      if (aLength == 0)
   341      {
   342          SuccessOrExit(error = message->Append(data, length));
   343      }
   344      else
   345      {
   346          for (index = 0; index < aLength; index++)
   347          {
   348              for (MeshCoP::Tlv *cur                                          = reinterpret_cast<MeshCoP::Tlv *>(data);
   349                   cur < reinterpret_cast<MeshCoP::Tlv *>(data + length); cur = cur->GetNext())
   350              {
   351                  if (cur->GetType() == aTlvs[index])
   352                  {
   353                      SuccessOrExit(error = message->AppendTlv(*cur));
   354                      break;
   355                  }
   356              }
   357          }
   358      }
   359
   360      if (message->GetLength() == message->GetOffset())
   361      {
   362          // no payload, remove coap payload marker
   363          message->SetLength(message->GetLength() - 1);
   364      }
   365
   366      SuccessOrExit(error = Get<Coap::Coap>().SendMessage(*message, aMessageInfo));
   367
   368      otLogInfoMeshCoP("sent commissioning dataset get response");
   369
   370  exit:
   371
   372      if (error != OT_ERROR_NONE && message != NULL)
   373      {
   374          message->Free();
   375      }
   376  }
